//! SDK for apps the web desktop loads at runtime.
//!
//! An app is a wasm module plus a JS entry that implements a small mount contract:
//!
//! ```text
//! init(wasm)          instantiate (generated by wasm-bindgen)
//! mount(el, host) -> id   render into `el`, using `host` for shell services
//! unmount(id)         tear down
//! ```
//!
//! [`app!`] generates all of that; the author writes one function. The host object
//! is passed as data rather than as wasm imports, so the same app also works behind
//! a sandboxed boundary later without an ABI rewrite.
//!
//! ```no_run
//! use app_sdk::prelude::*;
//!
//! app_sdk::app! {
//!     fn hello(ctx: Context) -> impl IntoView {
//!         let theme = ctx.theme();
//!         view! {
//!             <button
//!                 style=format!("color:{}", theme.accent)
//!                 on:click=move |_| ctx.log("clicked")
//!             >
//!                 "hello from a served app"
//!             </button>
//!         }
//!     }
//! }
//! ```
//!
//! # Do not enable `leptos/delegation` in an app
//!
//! The shell enables it, which means the shell has a `click` (and `pointerdown`, …)
//! listener on `window` that dispatches by looking for a `$$$click` *property* on
//! each node from the event target upwards. That property is a plain JS function, so
//! a second wasm instance using the same property name will be found by the shell's
//! walk and vice versa: every handler fires twice. Apps therefore attach direct
//! listeners, and `app-sdk` depends on `leptos` without the `delegation` feature.
//!
//! To read a cross-origin URL, turn on the `fetch` feature (see [`fetch`]): the request
//! goes through the server, because the browser will not let an app read a response
//! from a host without CORS headers.
//!
//! An app needs `crate-type = ["cdylib"]` and three dependencies: this crate, plus
//! `leptos` and `wasm-bindgen` — not by choice, but because `view!` expands to
//! absolute `leptos::` paths and `#[wasm_bindgen]` needs its crate in scope. Nothing
//! else has to be named: the re-exports below cover the rest.

mod context;
#[cfg(feature = "fetch")]
pub mod fetch;

// Reachable only so the generated mount/unmount in an app crate can call it; the
// `runtime::mount` path is part of the expansion, not of the public API.
#[doc(hidden)]
pub mod runtime;

pub use context::{Context, Size, Theme};

// Re-exported so an app crate needs exactly one dependency, and so the `app!`
// macro can name these through `$crate` rather than the caller's crate root.
pub use leptos;
pub use wasm_bindgen;
pub use web_sys;

/// Everything an app normally wants.
///
/// `leptos` and `wasm_bindgen` are re-exported so an app can name them without
/// depending on their internals, and so the paths the generated code needs resolve
/// from one import.
pub mod prelude {
    #[cfg(feature = "fetch")]
    pub use crate::fetch;
    pub use crate::{Context, Size, Theme};
    pub use leptos;
    pub use leptos::prelude::*;
    pub use leptos::view;
    pub use wasm_bindgen;
}

/// Declare the app, generating the mount contract the shell calls.
///
/// The function may be anything returning a view; it is called once per window,
/// so its signals are per-window state.
///
/// The signature is matched literally as `fn name(ctx: Context) -> impl IntoView`
/// because `$crate` is not allowed in a macro *matcher*. The expansion still refers
/// to the SDK through `$crate`, so an app crate needs no other dependency.
#[macro_export]
macro_rules! app {
    ($(#[$meta:meta])* $vis:vis fn $name:ident($ctx:ident: Context) -> impl IntoView $body:block) => {
        $(#[$meta])*
        $vis fn $name($ctx: Context) -> impl IntoView $body

        /// Renders the app into `element`. Called once per window; the returned id
        /// is handed back to `unmount`.
        #[$crate::wasm_bindgen::prelude::wasm_bindgen]
        pub fn mount(
            element: $crate::web_sys::HtmlElement,
            host: $crate::wasm_bindgen::JsValue,
        ) -> u32 {
            $crate::runtime::mount(element, host, $name)
        }

        /// Tears down the instance created by `mount`.
        #[$crate::wasm_bindgen::prelude::wasm_bindgen]
        pub fn unmount(id: u32) {
            $crate::runtime::unmount(id);
        }
    };
}
